8	function TierTabClass(key: TierKey, active: boolean): string {
9	  if (!active) return styles.tierTab;
10	  const map: Record<TierKey, string> = {
11	    small: cn(styles.tierTab, styles.tierTabActiveSmall),
12	    medium: cn(styles.tierTab, styles.tierTabActiveMedium),
13	    large: cn(styles.tierTab, styles.tierTabActiveLarge),
14	    support: cn(styles.tierTab, styles.tierTabActiveSupport),
15	  };
16	  return map[key];
17	}
18	
19	function TierIntroClass(key: TierKey): string {
20	  const map: Record<TierKey, string> = {
21	    small: cn(styles.tierIntro, styles.tierIntroSmall),
22	    medium: cn(styles.tierIntro, styles.tierIntroMedium),
23	    large: cn(styles.tierIntro, styles.tierIntroLarge),
24	    support: cn(styles.tierIntro, styles.tierIntroSupport),
25	  };
26	  return map[key];
27	}
28	
29	function TierIntroTagClass(key: TierKey): string {
30	  const map: Record<TierKey, string> = {
31	    small: cn(styles.tierIntroTag, styles.tierIntroTagSmall),
32	    medium: cn(styles.tierIntroTag, styles.tierIntroTagMedium),
33	    large: cn(styles.tierIntroTag, styles.tierIntroTagLarge),
34	    support: cn(styles.tierIntroTag, styles.tierIntroTagSupport),
35	  };
36	  return map[key];
37	}
