39	function CardClass(key: TierKey): string {
40	  const map: Record<TierKey, string> = {
41	    small: cn(styles.card, styles.cardSmall),
42	    medium: cn(styles.card, styles.cardMedium),
43	    large: cn(styles.card, styles.cardLarge),
44	    support: cn(styles.card, styles.cardSupport),
45	  };
46	  return map[key];
47	}
48	
49	function CardLabelClass(key: TierKey): string {
50	  const map: Record<TierKey, string> = {
51	    small: cn(styles.cardLabel, styles.cardLabelSmall),
52	    medium: cn(styles.cardLabel, styles.cardLabelMedium),
53	    large: cn(styles.cardLabel, styles.cardLabelLarge),
54	    support: cn(styles.cardLabel, styles.cardLabelSupport),
