58	
59	function PlatformContent({ platform }: { platform: Platform }) {
60	  const [activeTier, setActiveTier] = useState<TierKey>("small");
61	  const tier = platform.tiers.find((t) => t.key === activeTier) ?? platform.tiers[0];
62	
63	  const isShopifyLike = platform.iconVariant === "shopify" || platform.iconVariant === "shopify-apps";
64	
65	  const headerClass = isShopifyLike
66	    ? cn(styles.platformHeader, styles.platformHeaderShopify)
67	    : cn(styles.platformHeader, styles.platformHeaderWordpress);
68	
69	  const phIconClass = isShopifyLike
70	    ? cn(styles.phIconLarge, styles.phIconShopify)
71	    : cn(styles.phIconLarge, styles.phIconWp);
72	
73	  const phBadgeClass = isShopifyLike
74	    ? cn(styles.phBadge, styles.phBadgeShopify)
75	    : cn(styles.phBadge, styles.phBadgeWp);
76	
77	  return (
78	    <div>
79	      {/* Platform header */}
80	      <div className={headerClass}>
81	        <div className={phIconClass}>{platform.icon}</div>
82	        <div className={styles.phBody}>
83	          <p className={styles.phName}>{platform.name}</p>
84	          <p className={styles.phDesc}>{platform.description}</p>
85	        </div>
86	        <span className={phBadgeClass}>{platform.badge}</span>
87	      </div>
88	
89	      {/* Tier selector */}
90	      <div className={styles.tierTabs} role="tablist" aria-label="Task size">
91	        {platform.tiers.map((t) => (
92	          <button
93	            key={t.key}
94	            role="tab"
95	            aria-selected={activeTier === t.key}
96	            className={TierTabClass(t.key, activeTier === t.key)}
97	            onClick={() => setActiveTier(t.key)}
98	          >
99	            {t.icon} {t.name}
100	          </button>

